mapper.select:

SELECT m.id AS memberId,m.display_name AS displayName,m.status AS status,m.registered_at AS registeredAt,f.ever_paid AS everPaid,m.version AS version
FROM tc_member m JOIN tc_member_trade_fact f ON f.tenant_id=m.tenant_id AND f.member_id=m.id
WHERE m.tenant_id=#{tenant} AND m.identity_hash=#{identityHash} AND m.issuer=#{issuer} AND m.subject=#{subject}


SELECT m.id AS memberId,m.display_name AS displayName,m.status AS status,m.registered_at AS registeredAt,f.ever_paid AS everPaid,m.version AS version
FROM tc_member m JOIN tc_member_trade_fact f ON f.tenant_id=m.tenant_id AND f.member_id=m.id
WHERE m.tenant_id=#{tenant} AND m.id>#{after} ORDER BY m.id LIMIT #{limit}

SELECT m.id AS memberId,m.display_name AS displayName,m.status AS status,m.registered_at AS registeredAt,f.ever_paid AS everPaid,m.version AS version
FROM tc_member m JOIN tc_member_trade_fact f ON f.tenant_id=m.tenant_id AND f.member_id=m.id
WHERE m.tenant_id=#{tenant} AND m.id > #{q.after}
AND m.id=#{q.filters.memberId}
AND m.status=#{q.filters.status}
AND m.registered_at >= #{q.filters.registeredFrom} AND m.registered_at < #{q.filters.registeredTo}
ORDER BY m.id LIMIT #{q.limit}


SELECT action AS action,document_version AS documentVersion
FROM tc_member_consent WHERE tenant_id=#{tenant} AND member_id=#{memberId} AND purpose=#{purpose}
ORDER BY member_version DESC LIMIT 1 FOR UPDATE


SELECT id AS id,purpose AS purpose,document_version AS documentVersion,action AS action,member_version AS memberVersion,created_at AS occurredAt
FROM tc_member_consent
WHERE tenant_id=#{tenant} AND member_id=#{memberId} AND id>#{after} ORDER BY id LIMIT #{limit}
